<?php
class Reporte_anulaciones extends CI_Controller{
 private $session_data=array();
 public function __construct(){parent::__construct();if(!$this->session->userdata('logged_in'))redirect('','refresh');$this->session_data=$this->session->userdata('logged_in');$this->load->model('Reporte_anulaciones_model');$this->load->model('Sistema_model');$this->load->model('Parametro_model');if(!$this->Reporte_anulaciones_model->usuario_tiene_rol((int)$this->session_data['usuario_id'],220))show_error('No tiene permiso para generar reportes de Transporte.',403,'Acceso denegado');}
 private function filtros(){ $d=trim((string)$this->input->get('desde',true));$h=trim((string)$this->input->get('hasta',true));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d))$d=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$h))$h=date('Y-m-d');if($d>$h){$x=$d;$d=$h;$h=$x;}return array('desde'=>$d,'hasta'=>$h,'ruta_id'=>(int)$this->input->get('ruta_id',true),'vendedor_id'=>(int)$this->input->get('vendedor_id',true),'anulador_id'=>(int)$this->input->get('anulador_id',true));}
 public function index(){ $f=$this->filtros();$p=$this->Parametro_model->get_parametros();$data['sistema']=$this->Sistema_model->get_sistema();$data['parametro']=isset($p[0])?$p[0]:$p;$data['filtros']=$f;$data['listas']=$this->Reporte_anulaciones_model->listas();$data['filas']=$this->Reporte_anulaciones_model->reporte($f);$data['page_title']='Reporte de anulaciones';$data['_view']='reporte_transporte/anulaciones';$this->load->view('layouts/main',$data);}
 public function csv(){ $f=$this->filtros();$rs=$this->Reporte_anulaciones_model->reporte($f);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="anulaciones_'.$f['desde'].'_'.$f['hasta'].'.csv"');echo "\xEF\xBB\xBF";$x=fopen('php://output','w');fputcsv($x,array('Fecha anulacion','Ticket','Pasajero','Documento','Asiento','Ruta','Fecha viaje','Precio','Usuario vendedor','Usuario anuló','Usuario autorizó','Motivo','Venta ID','Pasaje ID'),';');foreach($rs as $r)fputcsv($x,array($r['fecha_anulacion'],$r['ticket'],$r['pasajero'],$r['documento'],$r['asiento'],$r['ruta'],$r['fecha_viaje'],$r['precio'],$r['vendedor'],$r['anulador'],$r['autorizador'],$r['motivo'],$r['venta_id'],$r['pasaje_id']),';');fclose($x);exit;}
}
